// Decodes the example github-octopus sprite (src/pixel_art/example_project.cljs) into a
// "drawing plan" the demo spec replays to paint the sprite from scratch on a blank project.
//
// Output: demo-out/octopus-plan.json  (regenerated by scripts/record-demo.sh; gitignored)
//
// Plan shape:
//   { size:{w,h},
//     palette:[{rgb:"r,g,b", hex:"RRGGBB"}],          // colors to add via the picker (bg first)
//     bgRgb:"r,g,b",
//     frames:[ { bgFill:bool,                          // true only for frame 0
//                paint:[{rgb, runs:[[y,x0,x1]], singles:[[x,y]]}],  // grouped by color
//                erase:{runs:[[y,x0,x1]], singles:[[x,y]]} } ] }     // empty for frame 0
//
// Strategy: frame 0 is drawn fully; frames 1-3 are drawn as the diff vs the previous frame
// (paint changed pixels, erase vanished pixels) — matching the demo's "duplicate then adjust".
const fs = require('fs');
const { execSync } = require('child_process');
const os = require('os');
const path = require('path');

const FF = require('ffmpeg-static');
const W = 50, H = 50;

const src = fs.readFileSync('src/pixel_art/example_project.cljs', 'utf8');
const b64s = [...src.matchAll(/base64,([A-Za-z0-9+/=]+)/g)].map((m) => m[1]);

function decode(i) {
  const png = path.join(os.tmpdir(), `oct${i}.png`);
  const raw = path.join(os.tmpdir(), `oct${i}.rgba`);
  fs.writeFileSync(png, Buffer.from(b64s[i], 'base64'));
  execSync(`"${FF}" -y -i ${png} -f rawvideo -pix_fmt rgba ${raw} 2>/dev/null`);
  const d = fs.readFileSync(raw);
  const g = [];
  for (let y = 0; y < H; y++) {
    g[y] = [];
    for (let x = 0; x < W; x++) {
      const p = (y * W + x) * 4;
      g[y][x] = d[p + 3] > 0 ? `${d[p]},${d[p + 1]},${d[p + 2]}` : null;
    }
  }
  return g;
}

const oct = [0, 2, 4, 6].map(decode);     // octopus layer cels
const bgRgb = decode(1)[0][0];            // background layer: solid fill

// Build run-length paint groups for a per-pixel color function (returns "r,g,b" or null).
function group(colorAt) {
  const byColor = new Map();
  for (let y = 0; y < H; y++) {
    let x = 0;
    while (x < W) {
      const c = colorAt(x, y);
      if (c === null) { x++; continue; }
      let x1 = x;
      while (x1 + 1 < W && colorAt(x1 + 1, y) === c) x1++;
      if (!byColor.has(c)) byColor.set(c, { rgb: c, runs: [], singles: [] });
      if (x1 > x) byColor.get(c).runs.push([y, x, x1]);
      else byColor.get(c).singles.push([x, y]);
      x = x1 + 1;
    }
  }
  return [...byColor.values()];
}

// Each frame is drawn fully on a fresh (empty) octopus cel — the background is a separate
// auto-linked layer, so new frames inherit it and only the octopus is painted per frame.
const frames = oct.map((g) => ({ paint: group((x, y) => g[y][x]) }));

const toHex = (rgb) => rgb.split(',').map((n) => (+n).toString(16).padStart(2, '0')).join('').toUpperCase();
// Palette to add via the picker: background first, then every octopus color (union of all frames).
const octColors = [...new Set(frames.flatMap((f) => f.paint.map((p) => p.rgb)))];
const palette = [bgRgb, ...octColors].map((rgb) => ({ rgb, hex: toHex(rgb) }));

const plan = { size: { w: W, h: H }, palette, bgRgb, frames };
fs.mkdirSync('demo-out', { recursive: true });
fs.writeFileSync('demo-out/octopus-plan.json', JSON.stringify(plan));
const ops = frames.reduce((s, f) => s + f.paint.reduce((a, p) => a + p.runs.length + p.singles.length, 0), 0);
console.log(`octopus-plan.json written: ${palette.length} colors, ${ops} draw ops across ${frames.length} frames`);
